  2722      switch (fp->format.format) {
  2723      case bam: {
  2724          int r = bam_read1(fp->fp.bgzf, b);
  2725          if (h && r >= 0) {
  2726              if (b->core.tid  >= h->n_targets || b->core.tid  < -1 ||
  2727                  b->core.mtid >= h->n_targets || b->core.mtid < -1) {
  2728                  errno = ERANGE;
  2729                  return -3;
  2730              }
  2731          }
  2732          return r;
  2733          }
  2734
  2735      case cram: {
  2736          int ret = cram_get_bam_seq(fp->fp.cram, &b);
  2737          if (ret < 0)
  2738              return cram_eof(fp->fp.cram) ? -1 : -2;
  2739
  2740          if (bam_tag2cigar(b, 1, 1) < 0)
  2741              return -2;
  2742          return ret;
  2743      }
  2744
  2745      case sam: {
  2746          // Consume 1st line after header parsing as it wasn't using peek
  2747          if (fp->line.l != 0) {
  2748              int ret = sam_parse1(&fp->line, h, b);
  2749              fp->line.l = 0;
  2750              return ret;
  2751          }
  2752
  2753          if (fp->state) {
  2754              SAM_state *fd = (SAM_state *)fp->state;
  2755
  2756              if (fp->format.compression == bgzf && fp->fp.bgzf->seeked) {
  2757                  // We don't support multi-threaded SAM parsing with seeks yet.
  2758                  int ret;
  2759                  if ((ret = sam_state_destroy(fp)) < 0) {
  2760                      errno = -ret;
  2761                      return -2;
  2762                  }
  2763                  if (bgzf_seek(fp->fp.bgzf, fp->fp.bgzf->seeked, SEEK_SET) < 0)
  2764                      return -1;
  2765                  fp->fp.bgzf->seeked = 0;
  2766                  goto err_recover;
  2767              }
  2768
  2769              if (!fd->h) {
  2770                  fd->h = h;
  2771                  fd->h->ref_count++;
  2772                  // Ensure hrecs is initialised now as we don't want multiple
  2773                  // threads trying to do this simultaneously.
  2774                  if (!fd->h->hrecs && sam_hdr_fill_hrecs(fd->h) < 0)
  2775                      return -2;
  2776
