  2778                  if (pthread_create(&fd->dispatcher, NULL, sam_dispatcher_read, fp) != 0)
  2779                      return -2;
  2780              }
  2781
  2782              if (fd->h != h) {
  2783                  hts_log_error("SAM multi-threaded decoding does not support changing header");
  2784                  return -1;
  2785              }
  2786
  2787              sp_bams *gb = fd->curr_bam;
  2788              if (!gb) {
  2789                  if (fd->errcode) {
  2790                      // Incase reader failed
  2791                      errno = fd->errcode;
  2792                      return -2;
  2793                  }
  2794                  hts_tpool_result *r = hts_tpool_next_result_wait(fd->q);
  2795                  if (!r)
  2796                      return -2;
  2797                  fd->curr_bam = gb = (sp_bams *)hts_tpool_result_data(r);
  2798                  hts_tpool_delete_result(r, 0);
  2799              }
  2800              if (!gb)
  2801                  return fd->errcode ? -2 : -1;
  2802              bam1_t *b_array = (bam1_t *)gb->bams;
  2803              if (fd->curr_idx < gb->nbams)
  2804                  if (!bam_copy1(b, &b_array[fd->curr_idx++]))
  2805                      return -2;
  2806              if (fd->curr_idx == gb->nbams) {
  2807                  pthread_mutex_lock(&fd->lines_m);
  2808                  gb->next = fd->bams;
  2809                  fd->bams = gb;
  2810                  pthread_mutex_unlock(&fd->lines_m);
