  2812                  fd->curr_bam = NULL;
  2813                  fd->curr_idx = 0;
  2814              }
  2815
  2816              return 0;
  2817
  2818          } else  {
  2819              int ret;
  2820          err_recover:
  2821
  2822              ret = hts_getline(fp, KS_SEP_LINE, &fp->line);
  2823              if (ret < 0) return ret;
  2824
  2825              ret = sam_parse1(&fp->line, h, b);
  2826              fp->line.l = 0;
  2827              if (ret < 0) {
  2828                  hts_log_warning("Parse error at line %lld", (long long)fp->lineno);
  2829                  if (h->ignore_sam_err) goto err_recover;
  2830              }
  2831              return ret;
  2832          }
  2833      }
