  2854      r |= kputc_('\t', str); // query name
  2855      r |= kputw(c->flag, str); r |= kputc_('\t', str); // flag
  2856      if (c->tid >= 0) { // chr
  2857          r |= kputs(h->target_name[c->tid] , str);
  2858          r |= kputc_('\t', str);
  2859      } else r |= kputsn_("*\t", 2, str);
  2860      r |= kputll(c->pos + 1, str); r |= kputc_('\t', str); // pos
