  2991                  for (i = 0; i < n; ++i) {r |= kputc_(',', str); r |= kputw(le_to_u16(s), str); s += 2; }
  2992                  break;
  2993              case 'i':
  2994                  if (ks_resize(str, str->l + n*6) < 0) goto mem_err;
  2995                  for (i = 0; i < n; ++i) {r |= kputc_(',', str); r |= kputw(le_to_i32(s), str); s += 4; }
  2996                  break;
  2997              case 'I':
  2998                  if (ks_resize(str, str->l + n*6) < 0) goto mem_err;
  2999                  for (i = 0; i < n; ++i) {r |= kputc_(',', str); r |= kputuw(le_to_u32(s), str); s += 4; }
  3000                  break;
  3001              case 'f':
  3002                  if (ks_resize(str, str->l + n*8) < 0) goto mem_err;
  3003                  for (i = 0; i < n; ++i) {r |= kputc_(',', str); r |= kputd(le_to_float(s), str); s += 4; }
  3004                  break;
  3005              default:
  3006                  goto bad_aux;
  3007              }
  3008          } else { // Unknown type
  3009              goto bad_aux;
  3010          }
  3011      }
  3012      r |= kputsn("", 0, str); // nul terminate
  3013      if (r < 0) goto mem_err;
